public class Foo {
    public Object foo() {
        Object x = null; // OK
        System.out.println(x); // report: value is null
        return x; // report: return null
    }
}

public class Foo {
    public Object foo() {
        Object x = null;
        if (bar()) {
            x = new Object();
        }
        System.out.println(x);
        return x;
    }
    private boolean bar() { }
}

public class Foo {
    public Object foo() {
        Object x;
        if (bar()) {
            x = null;
        } else {
            x = null;
        }
        System.out.println(x);
        return x;
    }

    private boolean bar() {
    }
}

public class Foo {
    public Object foo() {
        Object x;
        if (bar() || true) {
            x = null;
        } else {
            x = new Object();
        }
        System.out.println(x);
        return x;
    }
    private boolean bar() { }
}

public class Foo {
    public void foo() {
        Object x;
        if (x == null) { // This is OK
            return;
        }
    }
}

public class Foo {
    public void foo() {
        String x = null;
        x = new String(null);
    }
}

public class Foo {
    public void foo() {
        String x = bar() ? "fiz" : null;
    }
    private boolean bar() { return false; }
}

public class Foo {
    public void foo() {
        String x;
        x = bar() ? "fiz" : null;
        System.out.println(x); // fine, x is nullable
    }
    private boolean bar() { return false; }
}

public class Foo {
    public String foo(String x) {
        return x == null ? "42" : x;
    }
}

public class Foo {
    private final String x;
    public Foo(String y) {
        x = null;
    }

    void foo() {
        System.out.println(x); // report: variable is always null
    }
}
